const Texture& TextureFor(TextureId id) {
    switch (id) {
        case kTexBrick:
            return kBrick;
        case kTexStone:
            return kStone;
        case kTexTech:
            return kTech;
        case kTexFlesh:
            return kFlesh;
        case kTexWood:
            return kWood;
        case kTexDoor:
            return kDoor;
        case kTexExit:
            return kExit;
        case kTexFloor:
            return kFloor;
        case kTexCeiling:
            return kCeiling;
        default:
            return kBrick;
    }
}

